playerDamaged.Name = "PlayerDamaged";
playerDamaged.Parent = ReplicatedStorage;

const updateHealth = new Instance("RemoteEvent");
updateHealth.Name = "UpdateHealth";
updateHealth.Parent = ReplicatedStorage;

export { playerDamaged, updateHealth };

// server/combat.server.ts
import { Players } from "@rbxts/services";
import { playerDamaged, updateHealth } from "shared/remotes";

playerDamaged.OnServerEvent.Connect((player, ...args) => {
    const targetId = args[0] as string;
    const damage = args[1] as number;
    print(`${player.Name} damaged ${targetId} for ${damage}`);
});

// Fire to client
updateHealth.FireClient(SomePlayer, 75);

// client/ui.client.ts
import { playerDamaged, updateHealth } from "shared/remotes";

updateHealth.OnClientEvent.Connect((health: unknown) => {
    print(`Health updated: ${health}`);
