## Common Patterns

### Remote Events with Type Safety

```typescript
// shared/remotes.ts
import { ReplicatedStorage } from "@rbxts/services";

const remotes = {
    playerDamaged: new Instance("RemoteEvent", ReplicatedStorage),
    updateHealth: new Instance("RemoteEvent", ReplicatedStorage),
};

// server/combat.server.ts
import remotes from "shared/remotes";

remotes.playerDamaged.OnServerEvent.Connect((player, ...args) => {
    const targetId = args[0] as string;
    const damage = args[1] as number;
    print(`${player.Name} damaged ${targetId} for ${damage}`);
});

// Fire to client
remotes.updateHealth.FireClient(player, 75);

// client/ui.client.ts
import remotes from "shared/remotes";

remotes.updateHealth.OnClientEvent.Connect((health: number) => {
    print(`Health updated: ${health}`);
});

// Fire to server
remotes.playerDamaged.FireServer("enemy-123", 25);
```

### Data Stores with Type Safety

```typescript
import { DataStoreService } from "@rbxts/services";

interface PlayerData {
    coins: number;
    level: number;
    inventory: string[];
}

const dataStore = DataStoreService.GetDataStore("PlayerData");

function savePlayerData(userId: string, data: PlayerData) {
    const success = pcall(() => {
        dataStore.SetAsync(userId, data);
    })[0];

    return success;
}

function loadPlayerData(userId: string): PlayerData | undefined {
    const [success, data] = pcall(() => {
        return dataStore.GetAsync(userId) as PlayerData | undefined;
    });

    return success ? data : undefined;
}
```

### Character Management

```typescript
import { Players } from "@rbxts/services";

function setupCharacter(player: Player) {
    const character = player.Character || player.CharacterAdded.Wait()[0];
    const humanoid = character.WaitForChild("Humanoid") as Humanoid;
    const rootPart = character.WaitForChild("HumanoidRootPart") as Part;

    humanoid.Died.Connect(() => {
        print(`${player.Name} died`);
    });

    return { character, humanoid, rootPart };
}

Players.PlayerAdded.Connect((player) => {
    player.CharacterAdded.Connect(() => {
        setupCharacter(player);
    });
});
```

### GUI with Roact

```typescript
